    Microsoft.Extensions.ML.PredictionEnginePoolOptions<TicketInput, TicketPrediction>>>()
    .CurrentValue.ModelLoader = new Microsoft.ML.ModelLoader(trainer.ModelPath);

app.MapControllers();
app.Run();

